/* Seattle curb ramp hotspots. Data from data.js (window.HOTSPOTS),
 * generated by scripts/hotspots.rb. */
"use strict";

const H = window.HOTSPOTS;
const REPO = "olivierlacan/trebuche";
const esc = s => String(s ?? "").replace(/[&<>"']/g, ch => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[ch]));
const fmt = n => n.toLocaleString("en-US");
const T = H.totals;

// ------------------------------------------------------------ stats
const pct = Math.round((100 * T.no_ramp) / T.with_sidewalk);
document.getElementById("stat-grid").innerHTML = [
  [fmt(T.no_ramp), `intersections with a sidewalk but <strong>no curb ramp</strong> (${pct}%)`],
  [fmt(T.ramps), "intersections where SDOT has recorded ramps"],
  [fmt(T.unknown), "with no record either way"],
  [H.hotspots.length, `hotspots of ${H.hot_min} or more no-ramp intersections within about four blocks`],
].map(([n, label]) => `<div class="stat"><div class="n"><span>${n}</span></div><div class="label">${label}</div></div>`).join("");

// ------------------------------------------------------------ map
const map = L.map("hotmap", { preferCanvas: true, scrollWheelZoom: false, maxZoom: 19 });
L.tileLayer("https://tile.openstreetmap.org/{z}/{x}/{y}.png", {
  maxZoom: 19,
  attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
}).addTo(map);
map.attributionControl.addAttribution("SDOT, Project Sidewalk");
map.on("focus", () => map.scrollWheelZoom.enable());
map.on("blur", () => map.scrollWheelZoom.disable());

// Grid cells, shaded by no-ramp count (only intersections with a sidewalk).
const [CLAT, CLON] = H.cell;
const cells = new Map();
for (const [lat, lon, st, sw] of H.points) {
  if (st !== 2 || !sw) continue;
  const k = `${Math.floor(lat / CLAT)},${Math.floor(lon / CLON)}`;
  cells.set(k, (cells.get(k) || 0) + 1);
}
const maxCell = Math.max(...cells.values());
const cellColor = n => {
  const t = Math.min(1, (n - 1) / (maxCell - 1 || 1));
  // pale yellow -> orange -> deep red
  const stops = [[255, 230, 140], [240, 140, 40], [150, 20, 30]];
  const [a, b, u] = t < 0.5 ? [stops[0], stops[1], t * 2] : [stops[1], stops[2], (t - 0.5) * 2];
  return `rgb(${a.map((v, i) => Math.round(v + (b[i] - v) * u)).join(",")})`;
};
const cellLayer = L.layerGroup([...cells].map(([k, n]) => {
  const [i, j] = k.split(",").map(Number);
  return L.rectangle([[i * CLAT, j * CLON], [(i + 1) * CLAT, (j + 1) * CLON]], {
    weight: 0, fillColor: cellColor(n), fillOpacity: n >= H.hot_min ? 0.6 : 0.35, hot: n >= H.hot_min,
  }).bindTooltip(`${n} intersection${n > 1 ? "s" : ""} with no curb ramp`);
})).addTo(map);

// Intersections: no-ramp always (black), the rest on request.
const dot = (st, sw) => st === 2
  ? { radius: 3.5, color: "#fff", weight: 1, fillColor: sw ? "#111" : "#888", fillOpacity: 1 }
  : st === 1 ? { radius: 2.5, color: "#1a8a4a", weight: 0, fillColor: "#1a8a4a", fillOpacity: 0.8 }
  : { radius: 2.5, color: "#999", weight: 0, fillColor: "#999", fillOpacity: 0.7 };
const label = st => ["no record either way", "SDOT has recorded ramps", "no curb ramp"][st];
const mkDots = filter => L.layerGroup(H.points.filter(filter).map(([lat, lon, st, sw, name]) =>
  L.circleMarker([lat, lon], dot(st, sw)).bindPopup(`<strong>${esc(name)}</strong><br>${label(st)}` +
    (sw ? "" : "<br><em>no sidewalk recorded here</em>") +
    `<br><a href="https://www.google.com/maps/@?api=1&map_action=pano&viewpoint=${lat},${lon}" target="_blank" rel="noopener">Street View</a>`)));
const noneDots = mkDots(p => p[2] === 2 && p[3]);
const otherDots = mkDots(p => p[2] !== 2 && p[3]);
const DOT_ZOOM = 14;
const syncDots = () => {
  const z = map.getZoom();
  z >= DOT_ZOOM ? noneDots.addTo(map) : noneDots.remove();
  z >= DOT_ZOOM && document.getElementById("show-all").checked ? otherDots.addTo(map) : otherDots.remove();
};
map.on("zoomend", syncDots);
// Lighter squares up close, so streets and dots stay readable.
map.on("zoomend", () => {
  const close = map.getZoom() >= 15;
  cellLayer.eachLayer(r => r.setStyle({ fillOpacity: (r.options.hot ? 0.6 : 0.35) * (close ? 0.4 : 1) }));
});
document.getElementById("show-all").addEventListener("change", e => {
  if (e.target.checked && map.getZoom() < DOT_ZOOM) map.setZoom(DOT_ZOOM);
  syncDots();
});
document.getElementById("map-key").textContent = `Zoom in to see intersections: black, no ramp; green, ramps recorded; gray, unknown.`;

// Numbered hotspot markers.
const markers = H.hotspots.map((s, i) => L.marker([s.lat, s.lon], {
  icon: L.divIcon({ className: "", html: `<div class="hot-label">${i + 1}</div>`, iconSize: [26, 26], iconAnchor: [13, 13] }),
  title: `Hotspot ${i + 1}: ${s.name}`, keyboard: true,
}).on("click", () => focusSpot(i, true)).addTo(map));

const params = new URLSearchParams(location.search);
const startSpot = Number(params.get("spot")) - 1;
const allPts = H.points.filter(p => p[3]).map(p => [p[0], p[1]]);
map.fitBounds(L.latLngBounds(allPts), { padding: [10, 10] });

function focusSpot(i, scrollToCard) {
  const s = H.hotspots[i];
  map.fitBounds(s.bounds, { padding: [20, 20], maxZoom: 16 });
  markers.forEach((m, j) => m.getElement()?.firstChild?.classList.toggle("sel", j === i));
  const u = new URL(location.href);
  u.searchParams.set("spot", i + 1);
  history.replaceState(null, "", u);
  if (scrollToCard) document.getElementById(`spot-${i + 1}`)?.scrollIntoView({ behavior: "smooth", block: "nearest" });
}

// ------------------------------------------------------------ hotspot cards
function issueUrl(s, i) {
  const title = `Organize a street: ${s.streets[0][0]} (${s.name})`;
  const body = [
    "<!-- Please don't include your name, phone, or email. -->",
    "",
    `Hotspot ${i + 1}: ${s.name} (council district ${s.district})`,
    `${s.no_ramp} intersections with no curb ramp. Streets: ${s.streets.map(([n, c]) => `${n} (${c})`).join(", ")}`,
    "",
    "Which street would you like a page for, and between which cross streets?",
    "",
    "Why this street (school, park, bus stop, errands)?",
    "",
    `Map: ${location.origin}${location.pathname}?spot=${i + 1}`,
  ].join("\n");
  return `https://github.com/${REPO}/issues/new?title=${encodeURIComponent(title)}&body=${encodeURIComponent(body)}&labels=new-street`;
}

const SHOWN = 12;
const list = document.getElementById("spots");
function renderSpots(n) {
  list.innerHTML = H.hotspots.slice(0, n).map((s, i) => `
    <li class="spot" id="spot-${i + 1}">
      <span class="rank">Hotspot ${i + 1} · Council District ${esc(s.district)}</span>
      <h3>${esc(s.name)}</h3>
      <span class="big"><strong>${s.no_ramp}</strong> of ${s.with_sidewalk} intersections with no curb ramp</span>
      <span class="bar" aria-hidden="true"><span style="width:${s.share}%"></span></span>
      <ul>${s.streets.map(([n, c]) => `<li>${esc(n)}: ${c}</li>`).join("")}</ul>
      <div class="acts">
        <button type="button" data-spot="${i}">Show on map</button>
        ${s.page ? `<a class="go" href="${esc(s.page)}">Street page →</a>` : `<a class="go" href="${esc(issueUrl(s, i))}" target="_blank" rel="noopener">Organize this one</a>`}
      </div>
    </li>`).join("");
  const more = document.getElementById("more-spots");
  more.hidden = n >= H.hotspots.length;
}
renderSpots(Number.isInteger(startSpot) && startSpot >= SHOWN ? H.hotspots.length : SHOWN);
document.getElementById("more-spots").addEventListener("click", () => renderSpots(H.hotspots.length));
list.addEventListener("click", e => {
  const b = e.target.closest("[data-spot]");
  if (!b) return;
  focusSpot(+b.dataset.spot, false);
  document.getElementById("hotmap").scrollIntoView({ behavior: "smooth", block: "center" });
});
if (startSpot >= 0 && H.hotspots[startSpot]) {
  focusSpot(startSpot, false);
}

// ------------------------------------------------------------ neighborhoods
const COLS = [
  ["name", "Neighborhood", s => esc(s)],
  ["no_ramp", "No ramp", n => fmt(n)],
  ["share", "Share", (v, r) => `${v}%<span class="share" aria-hidden="true"><span style="width:${v}%"></span></span>`],
  ["intersections", "Intersections", n => fmt(n)],
  ["ps_coverage", "Surveyed", n => `${n}%`],
  ["disability_pct", "Residents with a disability", n => (n == null ? "" : `${n}%`)],
];
const rows = H.neighborhoods.map(r => ({ ...r, share: Math.round((100 * r.no_ramp) / r.intersections) }));
let sort = { key: "no_ramp", dir: -1 };
function renderHoods() {
  const sorted = rows.slice().sort((a, b) => {
    const x = a[sort.key], y = b[sort.key];
    return (typeof x === "string" ? x.localeCompare(y) : (x ?? -1) - (y ?? -1)) * sort.dir;
  });
  document.getElementById("hoods").innerHTML =
    `<thead><tr>${COLS.map(([k, t]) => `<th scope="col" data-k="${k}" ${sort.key === k ? `aria-sort="${sort.dir < 0 ? "descending" : "ascending"}"` : ""} tabindex="0">${t}${sort.key === k ? (sort.dir < 0 ? " ↓" : " ↑") : ""}</th>`).join("")}</tr></thead>` +
    `<tbody>${sorted.map(r => `<tr>${COLS.map(([k, , f]) => `<td>${f(r[k], r)}</td>`).join("")}</tr>`).join("")}</tbody>`;
}
const hoodTable = document.getElementById("hoods");
const resort = e => {
  const th = e.target.closest("th[data-k]");
  if (!th || (e.type === "keydown" && e.key !== "Enter" && e.key !== " ")) return;
  e.preventDefault();
  const k = th.dataset.k;
  sort = { key: k, dir: sort.key === k ? -sort.dir : k === "name" ? 1 : -1 };
  renderHoods();
  hoodTable.querySelector(`th[data-k="${k}"]`).focus();
};
hoodTable.addEventListener("click", resort);
hoodTable.addEventListener("keydown", resort);
renderHoods();

document.getElementById("refreshed").textContent = `Data refreshed ${H.generated.slice(0, 10)}.`;
